let column = -1;
let locale = 'en-US';

export function setLocale(code: string) {
  locale = code;
  column = COLUMN[code.slice(0, 2).toLowerCase()] ?? -1;
  document.documentElement.lang = code.slice(0, 2);
}
export const getLocale = () => locale;

/** Translates an English string. Anything not in the dictionary, such as a server's own message, stays as it is. */
export function t(english: string, vars: Record<string, string | number> = {}): string {
  const row = column < 0 ? undefined : DICTIONARY[english];
  let out = row ? row[column]! : english;
  for (const [k, v] of Object.entries(vars)) out = out.split(`{${k}}`).join(String(v));
  return out;
}

/** The Rust core writes reasons in English: this turns them into the current language. */
export function reasonText(reason: string): string {
  const m = reason.match(/^(Because you liked|You often watch) (.+)$/);
  return m ? t(`${m[1]} {name}`, { name: m[2]! }) : t(reason);
}
